```mswea_bash_command
cat > /app/irc.py <<'PY'
import asyncio, sqlite3, os, re
DB='/app/data/huddle.db'
clients=set()
nicks=set()
def lookup(token):
    c=sqlite3.connect(DB); r=c.execute('SELECT u.id,u.username FROM tokens t JOIN users u ON u.id=t.user_id WHERE t.token=?',(token,)).fetchone(); c.close(); return r
async def send(w,s):
    try: w.write((s+'\r\n').encode()); await w.drain()
    except: pass
async def client(reader,writer):
    user=None; nick=None; authed=False; registered=False
    clients.add(writer)
    async def numeric(code,text=''):
        await send(writer,f':huddle 0{code} {nick or "*"} :{text}')
    try:
        while True:
            raw=await reader.readline()
            if not raw: break
            line=raw.decode(errors='replace').strip('\r\n')
            if not line: continue
            p=line.split(' ',1); cmd=p[0].upper(); arg=p[1] if len(p)>1 else ''
            if cmd=='PASS':
                token=arg.strip(); user=lookup(token)
                if not user: await numeric('464','Password incorrect')
                else: authed=True
            elif cmd=='NICK':
                new=arg.strip().split()[0] if arg.strip() else ''
                if new.lower() in nicks and new.lower()!=str(nick).lower():
                    await numeric('433','Nickname in use'); continue
                if nick: nicks.discard(nick.lower())
                nick=new; nicks.add(nick.lower())
                if authed and registered is False and user:
                    pass
            elif cmd=='USER':
                if authed and nick and not registered:
                    registered=True
                    for code,text in [('001','Welcome'),('002','Your host is huddle'),('003','This server was created today'),('004','huddle 1.0 aio'),('005','CHANTYPES=# :are supported'),('422','MOTD File is missing')]:
                        await numeric(code,text)
            elif cmd=='PING':
                await send(writer,':huddle PONG huddle :'+arg.lstrip(':'))
            elif cmd in ('PONG','NAMES','WHO','LIST','TOPIC','MODE'):
                if cmd=='NAMES': await numeric('353','= * :')
                elif cmd=='WHO': await numeric('315','End of WHO list')
                elif cmd=='LIST': await numeric('323','End of LIST')
                elif cmd=='TOPIC': await numeric('331','No topic is set')
            elif cmd=='QUIT':
                break
            else:
                await numeric('421',f'{cmd} Unknown command')
    except (asyncio.IncompleteReadError,ConnectionError):
        pass
    finally:
        clients.discard(writer)
        if nick: nicks.discard(nick.lower())
        writer.close()
        try: await writer.wait_closed()
        except: pass
async def main():
    s=await asyncio.start_server(client,'0.0.0.0',6667)
    async with s: await s.serve_forever()
if __name__=='__main__': asyncio.run(main())
