   m=__import__('json').loads(r['payload']).get('message',{}); body=m.get('body','')
   a=c.execute('SELECT username FROM users WHERE id=?',(m.get('author_id'),)).fetchone(); uname=a['username'] if a else 'user'; target='#'+r['slug']+'/'+r['name']
